#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
    Module containing loggin wraper class implementation. Highly configurable
    with JSON config file.

    Usage::

            from velocity.log import Log
            logger = Log.get_logger(__name__)
            Log.configure_logging(log_root_dir)

    SVN Keywords:

        Revision of last known commit:

            $Revision$

        The full URL of this file in the repository:

            $HeadURL$
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import logging
import logging.config
import os
import json

logger = logging.getLogger('log')
logger.setLevel(1)


class Log(object):
    """
        Adds console and file handlers. Default configuration is loaded from
        logging.json. Console output is enabled by default, but the respective
        log file handlers need to be added in the source logging configuration
        (.json) file!
    """

    @classmethod
    def get_logger(cls, name):
        """
            Default constructor.

            Arguments:
                name (str): File name of class that wants to get a logger. File
                    name must be same as one in logging.json file.

            Returns:
                logging: Logging module instance
        """

        cls.name = name
        cls.logger = logging.getLogger(cls.name)
        cls.logger.setLevel(1)
        return cls.logger

    @classmethod
    def configure_logging(cls,
                          log_root_dir=None,
                          console_log=True,
                          overwrite=False,
                          propagate=True):
        """
            Loads logging configuration from json file. If no log directory is
            given, will not add file handlers.

            Arguments:
                log_root_dir (str, optional): Optional directory path to folder
                    where logs should be saved.
                overwrite (bool, optional): If True, will overwrite the existing log
                    file. False by default. Will also delete additional log files up to .20
        """
        log_file = "velocityclient.log"
        topo_log_file = "topology.log"

        config = cls._load_json(cls._get_log_configuration_filepath())

        if config:
            if overwrite:
                if log_root_dir is None or log_root_dir == '.':
                    cls._remove_old_logs(log_file)
                    cls._remove_old_logs(topo_log_file)
                else:
                    cls._remove_old_logs(f"{log_root_dir}\\{log_file}")
                    cls._remove_old_logs(f"{log_root_dir}\\{topo_log_file}")

            if not console_log:
                config = cls._set_console_handlers(config)
            
            if not propagate:
                # Disable all propagation of log messages to parent loggers
                for logger_name in config["loggers"].keys():
                    config["loggers"][logger_name]["propagate"] = False

            if log_root_dir is not None:
                config = cls._add_root_dir_to_file_handlers_in_dictConfig(
                    config, log_root_dir
                )
            else:
                logger.debug(
                    "No log root directory given. Removing file handlers..."
                )
                config = cls._remove_file_handlers_from_dictConfig(config)
                logger.debug("File handlers removed from config.")

            try:
                logging.config.dictConfig(config)
                logger.debug(
                    "Logger {} configured with {}".format(
                        cls.name, cls._get_log_configuration_filepath()
                    )
                )

            except ValueError:
                logger.exception(
                    "Unable to load configuration file! Using "
                    "logging.basicConfig(level=logging.INFO)"
                )
                logging.basicConfig(level=logging.DEBUG)

    @staticmethod
    def _remove_old_logs(log_file: str) -> None:
        """
            Removes old log files and additional log files with .1, .2, etc. up to 20 instances.

            Arguments:
                log_file (str, required): address of the log file to be deleted

        """
        if os.path.isfile(log_file):
            os.remove(log_file)
            for i in range(1, 20):
                if os.path.isfile(f"{log_file}.{i}"):
                    os.remove(f"{log_file}.{i}")
                else:
                    break
        else:
            logger.info("No logs to be deleted.")

    @classmethod
    def _load_json(cls, json_path):
        """
            Loads JSON data from specified filepath.

            Arguments:
                json_path (str): Path to JSON file.

            Returns:
                str: Decoded JSON data.

            Raises:
                IOError: When unable to read file.
                ValueError: When unable to decode JSON data.
        """

        if os.path.isfile(json_path):

            try:
                with open(json_path, 'r') as infile:
                    data = json.load(infile)
                    infile.close()
            except ValueError:
                logger.exception("Unable to decode JSON data", exc_info=True)
                raise ValueError("Unable to decode JSON data")
        else:
            logger.error(
                "Unable to load data. File does not exist {}".format(json_path)
            )
            raise IOError(
                "Unable to load data. File does not exist: {}".format(
                    json_path
                )
            )

        return data

    @staticmethod
    def _get_log_configuration_filepath():
        """
            Get log configuration location (absolute).

            Returns:
                str: File path to log configuration.
        """

        return os.path.join(
            os.path.dirname(os.path.realpath(__file__)), "logging.json"
        )

    @classmethod
    def _set_console_handlers(cls, config):
        handlers = config["handlers"].keys()
        for h in list(handlers):
            if h.find("console") != -1:
                config["handlers"][h]["level"] = "WARNING"

        return config

    @classmethod
    def _remove_file_handlers_from_dictConfig(cls, config):
        # remove file handlers from handlers
        handlers = config["handlers"].keys()
        for h in list(handlers):
            if h.find("file") != -1:
                config["handlers"].pop(h, None)
                logger.debug(f"Removed handler '{h}' from config")

        # remove file handlers from loggers
        loggers = config["loggers"]
        for hh in loggers:
            if "handlers" in loggers[hh]:
                handler_list = loggers[hh]["handlers"]
                new_handler_list = \
                    [x for x in handler_list if x.find("file") == -1]
                config["loggers"][hh]["handlers"] = new_handler_list

        return config

    @classmethod
    def _add_root_dir_to_file_handlers_in_dictConfig(cls, config, log_root_dir):
        # add root directory to paths
        if os.path.isdir(log_root_dir):

            if "handlers" in config:
                handles = config["handlers"]

                file_handler_found = False
                for h in handles:
                    if h.find("file") != -1:
                        if "filename" in config["handlers"][h]:
                            filename = config["handlers"][h]["filename"]
                            filename = os.path.join(log_root_dir, filename)
                            config["handlers"][h]["filename"] = filename
                            logger.debug(
                                "File handler '{}' configured with new "
                                "filepath: {}".format(
                                    h, config["handlers"][h]["filename"]
                                )
                            )
                            file_handler_found = True
                        else:
                            logger.error(
                                "File handler {} does not contain string "
                                "'{}'".format(h, "filename")
                            )
                if not file_handler_found:
                    logger.warning(
                        "No file handlers found for {}. Make sure that all file"
                        " handlers have string 'file' in the logging "
                        "configuration json".format(handles)
                    )

            else:
                logger.error(
                    "Logging configuration file does not have handlers!"
                )
        return config
